// 세포 생물학 탐험 — 메인 앱. 페이지 전환 + 공용 레이아웃/배경.
import React, { useState } from 'react';
import Navigation, { PageId } from './components/Navigation';
import Background from './components/Background';
import Home from './pages/Home';
import CellDivision from './pages/CellDivision';
import DNAStructure from './pages/DNAStructure';
import Meiosis from './pages/Meiosis';

export default function App() {
  const [page, setPage] = useState<PageId>('home');

  const renderPage = () => {
    switch (page) {
      case 'mitosis': return <CellDivision />;
      case 'dna': return <DNAStructure />;
      case 'meiosis': return <Meiosis />;
      default: return <Home onNavigate={setPage} />;
    }
  };

  return (
    <div className="relative w-full h-screen flex flex-col overflow-hidden bg-gradient-to-br from-slate-950 via-indigo-950 to-slate-900 text-white">
      <Background />
      <div className="relative z-10 flex flex-col h-full min-h-0">
        <Navigation currentPage={page} onNavigate={setPage} />
        <main className="flex-1 min-h-0">
          {renderPage()}
        </main>
      </div>
    </div>
  );
}

