// ── DNA 염기 ──────────────────────────────────────────────────
export type BaseKey = 'A' | 'T' | 'G' | 'C';

export interface BaseInfo {
  key: BaseKey;
  ko: string;
  en: string;
  color: string;   // 염기 고유색 (hex)
  pair: BaseKey;   // 상보적으로 결합하는 염기
  bonds: number;   // 수소 결합 개수
  type: '퓨린' | '피리미딘';
}

export const BASES: Record<BaseKey, BaseInfo> = {
  A: { key: 'A', ko: '아데닌', en: 'Adenine', color: '#34d399', pair: 'T', bonds: 2, type: '퓨린' },
  T: { key: 'T', ko: '티민', en: 'Thymine', color: '#f87171', pair: 'A', bonds: 2, type: '피리미딘' },
  G: { key: 'G', ko: '구아닌', en: 'Guanine', color: '#fbbf24', pair: 'C', bonds: 3, type: '퓨린' },
  C: { key: 'C', ko: '사이토신', en: 'Cytosine', color: '#60a5fa', pair: 'G', bonds: 3, type: '피리미딘' },
};

export const BASE_ORDER: BaseKey[] = ['A', 'T', 'G', 'C'];

export function complement(base: BaseKey): BaseKey {
  return BASES[base].pair;
}

// ── 애니메이션 보간 유틸 ──────────────────────────────────────
export function clamp01(value: number): number {
  return value < 0 ? 0 : value > 1 ? 1 : value;
}

export function lerp(from: number, to: number, ratio: number): number {
  return from + (to - from) * ratio;
}

// 구간 [edge0, edge1] 동안 0 → 1 로 부드럽게 변하는 값 (Hermite smoothstep)
export function smoothstep(edge0: number, edge1: number, value: number): number {
  if (edge0 === edge1) return value < edge0 ? 0 : 1;
  const ratio = clamp01((value - edge0) / (edge1 - edge0));
  return ratio * ratio * (3 - 2 * ratio);
}

// 현재 진행도(t)가 어느 단계에 있는지 인덱스를 돌려준다.
export function phaseIndexAt(phases: Phase[], t: number): number {
  for (let index = phases.length - 1; index >= 0; index -= 1) {
    if (t >= phases[index].t0) return index;
  }
  return 0;
}

