// 타임라인 재생 훅 — 진행도(0~1)를 실시간으로 전진시킨다. 끝에 도달하면 자동 정지.
// JSX 없음 → .ts
import { useEffect, useRef, useState } from 'react';
import { clamp01 } from './biology';

export interface Playback {
  progress: number;
  playing: boolean;
  speed: number;
  scrub: (t: number) => void;
  toggle: () => void;
  reset: () => void;
  setSpeed: (s: number) => void;
}

export function usePlayback(durationSec: number): Playback {
  const [progress, setProgress] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [speed, setSpeed] = useState(1);

  const progressRef = useRef(0);
  const playingRef = useRef(false);
  const speedRef = useRef(1);
  const lastRef = useRef(0);
  const rafRef = useRef(0);

  speedRef.current = speed;
  playingRef.current = playing;

  useEffect(() => {
    const tick = (now: number) => {
      if (playingRef.current) {
        if (lastRef.current === 0) lastRef.current = now;
        const dt = (now - lastRef.current) / 1000;
        lastRef.current = now;
        let next = progressRef.current + (dt * speedRef.current) / durationSec;
        if (next >= 1) {
          next = 1;
          playingRef.current = false;
          setPlaying(false);
        }
        progressRef.current = next;
        setProgress(next);
      } else {
        lastRef.current = 0;
      }
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, [durationSec]);

  const scrub = (t: number) => {
    const value = clamp01(t);
    progressRef.current = value;
    setProgress(value);
  };

  const toggle = () => {
    if (!playingRef.current && progressRef.current >= 1) {
      progressRef.current = 0;
      setProgress(0);
    }
    lastRef.current = 0;
    setPlaying(!playingRef.current);
  };

  const reset = () => {
    progressRef.current = 0;
    setProgress(0);
    setPlaying(false);
  };

  return { progress, playing, speed, scrub, toggle, reset, setSpeed };
}

