    };

    rafRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      width={WIDTH}
      height={HEIGHT}
      className="w-full h-full max-h-full object-contain"
    />
  );
}

function drawRung(
  ctx: CanvasRenderingContext2D,
  x: number, y1: number, y2: number, baseTop: BaseKey, baseBottom: BaseKey,
) {
  const mid = (y1 + y2) / 2;
  ctx.save();
  ctx.lineWidth = 3.2;
  ctx.lineCap = 'round';
  ctx.strokeStyle = BASES[baseTop].color;
  ctx.beginPath(); ctx.moveTo(x, y1); ctx.lineTo(x, mid - 2); ctx.stroke();
  ctx.strokeStyle = BASES[baseBottom].color;
  ctx.beginPath(); ctx.moveTo(x, mid + 2); ctx.lineTo(x, y2); ctx.stroke();
  ctx.restore();
}

function drawEnzyme(
  ctx: CanvasRenderingContext2D,
  x: number, y: number, fill: string, ring: string, radius: number,
) {
  ctx.save();
  ctx.beginPath();
  ctx.arc(x, y, radius + 3, 0, Math.PI * 2);
  ctx.fillStyle = ring;
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = fill;
  ctx.globalAlpha = 0.92;
  ctx.fill();
  ctx.restore();
}

