// A-T, G-C 규칙을 직접 손으로 맞춰 보며 익힌다.
import React, { useState } from 'react';
import { Check, X, RefreshCw, Trophy } from 'lucide-react';
import { BASES, BaseKey, BASE_ORDER, complement } from '../lib/biology';

const TEMPLATES: BaseKey[][] = [
  ['A', 'T', 'G', 'C', 'A'],
  ['G', 'C', 'A', 'T', 'T'],
  ['T', 'A', 'C', 'G', 'G'],
  ['C', 'G', 'T', 'A', 'C'],
  ['A', 'G', 'C', 'T', 'A'],
];

export default function BasePairQuiz() {
  const [round, setRound] = useState(0);
  const [answer, setAnswer] = useState<BaseKey[]>([]);
  const [checked, setChecked] = useState(false);
  const [score, setScore] = useState(0);
  const [solved, setSolved] = useState(0);

  const template = TEMPLATES[round % TEMPLATES.length];

  const addBase = (base: BaseKey) => {
    if (checked || answer.length >= template.length) return;
    setAnswer([...answer, base]);
  };
  const undo = () => {
    if (checked) return;
    setAnswer(answer.slice(0, -1));
  };
  const check = () => {
    if (answer.length !== template.length) return;
    setChecked(true);
    const allCorrect = template.every((base, index) => answer[index] === complement(base));
    if (allCorrect) {
      setScore(score + 1);
      setSolved(solved + 1);
    } else {
      setSolved(solved + 1);
    }
  };
  const next = () => {
    setRound(round + 1);
    setAnswer([]);
    setChecked(false);
  };

  const allCorrect = checked && template.every((base, index) => answer[index] === complement(base));

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm text-slate-300">
          <Trophy className="w-4 h-4 text-amber-400" />
          <span>맞힌 문제 <b className="text-amber-300">{score}</b> / {solved}</span>
        </div>
        <span className="text-xs text-slate-400">주형 가닥에 상보적인 염기를 순서대로 고르세요</span>
      </div>

      {/* 주형 가닥 */}
      <div>
        <p className="text-xs font-semibold text-cyan-300 mb-2">주형 가닥 (5' → 3')</p>
        <div className="flex gap-2">
          {template.map((base, index) => (
            <div
              key={`tmpl-${index}`}
              className="flex-1 aspect-square rounded-xl flex items-center justify-center text-2xl font-black text-slate-900 shadow-lg"
              style={{ backgroundColor: BASES[base].color }}
            >
              {base}
            </div>
          ))}
        </div>
      </div>

      {/* 결합 표시 */}
      <div className="flex justify-center gap-2 -my-2">
        {template.map((_, index) => (
          <div key={`bond-${index}`} className="flex-1 flex justify-center text-slate-500 text-lg leading-none">⋮</div>
        ))}
      </div>

      {/* 새 가닥 (사용자 입력) */}
      <div>
        <p className="text-xs font-semibold text-fuchsia-300 mb-2">내가 만드는 새 가닥 (3' → 5')</p>
        <div className="flex gap-2">
          {template.map((base, index) => {
            const picked = answer[index];
            const correct = picked === complement(base);
            return (
              <div
                key={`ans-${index}`}
                className="flex-1 aspect-square rounded-xl flex items-center justify-center text-2xl font-black relative border-2 transition-colors"
                style={{
                  backgroundColor: picked ? BASES[picked].color : 'rgba(255,255,255,0.04)',
                  borderColor: checked ? (correct ? '#4ade80' : '#f87171') : 'rgba(255,255,255,0.15)',
                  color: picked ? '#0f172a' : '#475569',
                }}
              >
                {picked ?? '?'}
                {checked && (
                  <span className="absolute -top-2 -right-2">
                    {correct
                      ? <Check className="w-5 h-5 text-emerald-400 bg-slate-900 rounded-full p-0.5" />
                      : <X className="w-5 h-5 text-red-400 bg-slate-900 rounded-full p-0.5" />}
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* 팔레트 */}
      {!checked && (
        <div className="flex gap-2 items-center">
          {BASE_ORDER.map((base) => (
            <button
              key={base}
              onClick={() => addBase(base)}
              className="flex-1 py-3 rounded-xl font-black text-lg text-slate-900 hover:scale-105 active:scale-95 transition-transform shadow"
              style={{ backgroundColor: BASES[base].color }}
            >
              {base}
              <span className="block text-[10px] font-medium opacity-70">{BASES[base].ko}</span>
            </button>
          ))}
          <button
            onClick={undo}
            className="px-4 py-3 rounded-xl bg-white/10 text-slate-200 text-sm hover:bg-white/20 transition-colors"
          >
            지우기
          </button>
        </div>
      )}

      {/* 액션 */}
      <div className="flex items-center gap-3">
        {!checked ? (
          <button
            onClick={check}
            disabled={answer.length !== template.length}
            className="flex-1 py-3 rounded-xl bg-emerald-500 text-slate-900 font-bold disabled:opacity-30 disabled:cursor-not-allowed hover:bg-emerald-400 transition-colors"
          >
            확인하기
          </button>
        ) : (
          <>
            <span className={`flex-1 py-3 rounded-xl text-center font-bold ${allCorrect ? 'bg-emerald-500/20 text-emerald-300' : 'bg-red-500/20 text-red-300'}`}>
              {allCorrect ? '정답! A-T, G-C 규칙을 완벽히 지켰어요 🎉' : '아쉬워요. A는 T와, G는 C와 짝을 이뤄요.'}
            </span>
            <button
              onClick={next}
              className="px-5 py-3 rounded-xl bg-fuchsia-500 text-white font-bold flex items-center gap-2 hover:bg-fuchsia-400 transition-colors"
            >
              <RefreshCw className="w-4 h-4" /> 다음 문제
            </button>
          </>
        )}
      </div>
    </div>
  );
}

