                <PairRow a="A" b="T" note="2중 수소결합" />
                <PairRow a="G" b="C" note="3중 수소결합" />
              </div>
            </div>

            {/* 구조 설명 */}
            <div className="rounded-2xl bg-white/5 border border-white/10 p-4 text-sm text-slate-300 leading-relaxed space-y-2">
              <p><b className="text-cyan-300">당-인산 골격</b>: 두 가닥의 바깥쪽 뼈대(리본). 안쪽 염기들이 사다리의 발판이 돼요.</p>
              <p><b className="text-fuchsia-300">역평행(antiparallel)</b>: 한 가닥은 5'→3', 다른 가닥은 3'→5' 로 서로 반대 방향이에요.</p>
              <p><b className="text-emerald-300">이중나선</b>: 10 염기쌍마다 한 바퀴씩 꼬여 나선이 되고, 큰 홈·작은 홈이 생겨요.</p>
            </div>
          </aside>
        </div>
      )}

      {/* ── 복제 탭 ── */}
      {tab === 'replication' && (
        <div className="flex-1 min-h-0 flex gap-3">
          <div className="flex-1 min-w-0 relative rounded-2xl bg-slate-950/40 border border-white/10 overflow-hidden grid place-items-center">
            <button
              onClick={() => setReplicationPlaying(!replicationPlaying)}
              className="absolute top-3 right-3 z-10 grid place-items-center w-10 h-10 rounded-full bg-white/10 text-slate-200 hover:bg-white/20 transition-colors"
            >
              {replicationPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 ml-0.5" />}
            </button>
            <div className="w-full h-full grid place-items-center p-3">
              <Replication playing={replicationPlaying} showLabels={showLabels} />
            </div>
          </div>
          <aside className="w-[360px] shrink-0 flex flex-col gap-3 overflow-y-auto pr-1">
            <div className="rounded-2xl bg-white/5 border border-white/10 p-4">
              <h2 className="text-xl font-black text-white mb-1">반보존적 복제</h2>
              <p className="text-sm text-slate-300 leading-relaxed">
                이중나선이 지퍼처럼 풀리고, 각 가닥이 <b className="text-white">주형</b>이 되어 상보적인 새 가닥을 만들어요.
                그래서 새 DNA는 <b className="text-white">옛 가닥 1 + 새 가닥 1</b> 로 이루어집니다.
              </p>
            </div>
            <div className="rounded-2xl bg-white/5 border border-white/10 p-4 space-y-2.5 text-sm text-slate-300">
              <LegendRow color="#f9fafb" title="헬리케이스" desc="이중나선을 풀어 분기점을 만들어요" />
              <LegendRow color="#a3e635" title="선도가닥" desc="분기점을 따라 연속으로 합성" />
              <LegendRow color="#fbbf24" title="지연가닥" desc="짧은 조각(오카자키 절편)으로 합성" />
              <LegendRow color="#22d3ee" title="DNA 중합효소" desc="새 염기를 5'→3' 방향으로 이어 붙여요" />
            </div>
          </aside>
        </div>
      )}

      {/* ── 퀴즈 탭 ── */}
      {tab === 'quiz' && (
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className="max-w-2xl mx-auto rounded-2xl bg-white/5 border border-white/10 p-6">
            <BasePairQuiz />
          </div>
        </div>
      )}
    </div>
  );
}

function BaseChip({ base }: { base: BaseKey }) {
  return (
    <div className="text-center">
      <div
        className="w-14 h-14 rounded-2xl grid place-items-center text-3xl font-black text-slate-900 shadow-lg"
        style={{ backgroundColor: BASES[base].color }}
      >
        {base}
      </div>
      <div className="text-[11px] text-slate-400 mt-1">{BASES[base].ko}</div>
    </div>
  );
}

function PairRow({ a, b, note }: { a: BaseKey; b: BaseKey; note: string }) {
  return (
    <div className="flex items-center gap-2">
      <span className="w-8 h-8 rounded-lg grid place-items-center font-black text-slate-900" style={{ backgroundColor: BASES[a].color }}>{a}</span>
      <span className="text-slate-500">↔</span>
      <span className="w-8 h-8 rounded-lg grid place-items-center font-black text-slate-900" style={{ backgroundColor: BASES[b].color }}>{b}</span>
      <span className="text-xs text-slate-400 ml-2">{note}</span>
    </div>
  );
}

function LegendRow({ color, title, desc }: { color: string; title: string; desc: string }) {
  return (
    <div className="flex items-start gap-2.5">
      <span className="mt-1 w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: color }} />
      <span><b className="text-white">{title}</b> — {desc}</span>
    </div>
  );
}

